package dev.veltraph.client.navigation;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

final class NativeCarryPublicationWitnessTest {
    private static final class F {
        final Object mode=new Object(),client=new Object(),listener=new Object(),transport=new Object(),packet=new Object();
        final NativeCarryPublicationWitness w=new NativeCarryPublicationWitness(mode,client,listener,transport,7);
        void cache(){assertTrue(w.enter(mode,client,listener,true));assertTrue(w.beforeCache(mode,7,true));w.assignmentStaged();}
        void offer(){cache();assertTrue(w.offer(listener,packet,7,true));}
        void sent(){offer();assertTrue(w.beforeTransport(listener,transport,packet,true));w.transportReturned(true);assertTrue(w.beforeCommit(true));w.cacheReturned();w.bodyReturned(true);}
    }
    @Test void exactNativePacketNormalReturnConfirmsSubmissionNotServerAck(){var f=new F();f.sent();assertTrue(f.w.submitted());assertTrue(f.w.confirmed(true));}
    @Test void nativeCachedEqualityNoOpCannotCertifyPacket(){var f=new F();assertTrue(f.w.enter(f.mode,f.client,f.listener,true));f.w.bodyReturned(true);assertFalse(f.w.submitted());assertFalse(f.w.confirmed(true));}
    @Test void invocationWithoutTransportReturnCannotCertifyPacket(){var f=new F();f.offer();assertTrue(f.w.beforeTransport(f.listener,f.transport,f.packet,true));f.w.bodyReturned(true);assertFalse(f.w.submitted());assertFalse(f.w.confirmed(true));}
    @Test void originalTransportFailureHasNoNormalPacketReceipt(){var f=new F();f.offer();assertTrue(f.w.beforeTransport(f.listener,f.transport,f.packet,true));f.w.transportReturned(false);f.w.bodyReturned(false);assertFalse(f.w.submitted());assertFalse(f.w.confirmed(true));}
    @Test void foreignTransportCannotCreditCurrentSender(){var f=new F();f.offer();assertFalse(f.w.beforeTransport(f.listener,new Object(),f.packet,true));f.w.transportReturned(true);f.w.bodyReturned(true);assertFalse(f.w.submitted());assertFalse(f.w.confirmed(true));}
    @Test void differentMatchingSlotPacketCannotCreditExactOriginal(){var f=new F();f.offer();assertFalse(f.w.beforeTransport(f.listener,f.transport,new Object(),true));f.w.bodyReturned(true);assertFalse(f.w.submitted());}
    @Test void staleSourceBeforeNativeCacheRefusesEffect(){var f=new F();assertTrue(f.w.enter(f.mode,f.client,f.listener,true));assertFalse(f.w.beforeCache(f.mode,7,false));assertFalse(f.w.submitted());}
    @Test void configAbaAfterNativeConstructorRefusesSend(){var f=new F();f.cache();assertFalse(f.w.offer(f.listener,f.packet,7,false));assertFalse(f.w.submitted());}
    @Test void lateWorldReplacementAtTransportRefusesSend(){var f=new F();f.offer();assertFalse(f.w.beforeTransport(f.listener,f.transport,f.packet,false));assertFalse(f.w.submitted());}
    @Test void lateOwnerHpOrSlotSourceRefusalCannotBecomeReceipt(){for(int i=0;i<3;i++){var f=new F();f.offer();assertFalse(f.w.beforeTransport(f.listener,f.transport,f.packet,false));f.w.bodyReturned(true);assertFalse(f.w.confirmed(true));}}
    @Test void foreignHistoryAfterRealSubmissionRevokesConfirmationWithoutErasingSubmission(){var f=new F();f.sent();assertTrue(f.w.submitted());assertFalse(f.w.confirmed(false));}
    @Test void cacheAssignmentAloneIsNotPacketOrAck(){var f=new F();f.cache();f.w.bodyReturned(true);assertFalse(f.w.submitted());assertFalse(f.w.confirmed(true));}
    @Test void secondTransportCannotCertifyDuplicateEffect(){var f=new F();f.sent();assertFalse(f.w.beforeTransport(f.listener,f.transport,f.packet,true));assertFalse(f.w.confirmed(true));}
    @Test void unclaimedCacheReturnCannotForgeNativeSequence(){var f=new F();assertTrue(f.w.enter(f.mode,f.client,f.listener,true));f.w.cacheReturned();assertFalse(f.w.offer(f.listener,f.packet,7,true));assertFalse(f.w.submitted());}
    @Test void foreignNativeClientRefusesBeforeCache(){var f=new F();assertFalse(f.w.enter(f.mode,new Object(),f.listener,true));assertFalse(f.w.beforeCache(f.mode,7,true));assertFalse(f.w.submitted());}
    @Test void foreignNativeListenerRefusesBeforeCache(){var f=new F();assertFalse(f.w.enter(f.mode,f.client,new Object(),true));assertFalse(f.w.beforeCache(f.mode,7,true));assertFalse(f.w.submitted());}
    @Test void foreignListenerCannotSupplyTransportReturn(){var f=new F();f.offer();assertFalse(f.w.beforeTransport(new Object(),f.transport,f.packet,true));f.w.transportReturned(true);f.w.bodyReturned(true);assertFalse(f.w.submitted());assertFalse(f.w.confirmed(true));}
    @Test void failedTransportThenUnclaimedNormalReturnCannotForgeSubmission(){var f=new F();f.offer();assertTrue(f.w.beforeTransport(f.listener,f.transport,f.packet,true));f.w.transportReturned(false);f.w.transportReturned(true);f.w.bodyReturned(true);assertFalse(f.w.submitted());assertFalse(f.w.confirmed(true));}
    @Test void laterNativeBodyFailurePreservesRealSubmissionAndRefusesConfirmation(){var f=new F();f.offer();assertTrue(f.w.beforeTransport(f.listener,f.transport,f.packet,true));f.w.transportReturned(true);f.w.bodyReturned(false);assertTrue(f.w.submitted());assertFalse(f.w.confirmed(true));}
    @Test void duplicateCacheAdmissionCannotBecomeNativeAssignmentReceipt(){var f=new F();assertTrue(f.w.enter(f.mode,f.client,f.listener,true));assertTrue(f.w.beforeCache(f.mode,7,true));assertFalse(f.w.beforeCache(f.mode,7,true));f.w.cacheReturned();assertFalse(f.w.offer(f.listener,f.packet,7,true));assertFalse(f.w.submitted());}
    @Test void secondNativeBodyReturnCannotConfirmOriginal(){var f=new F();f.sent();f.w.bodyReturned(true);assertTrue(f.w.submitted());assertFalse(f.w.confirmed(true));}
    @Test void duplicateTransportReturnPreservesOnlyRealSubmission(){var f=new F();f.sent();f.w.transportReturned(true);assertTrue(f.w.submitted());assertFalse(f.w.confirmed(true));}

    @Test void figRefusedNormalListenerReturnWithoutActualTransportCannotCertifyPacket(){var f=new F();f.offer();f.w.bodyReturned(true);assertFalse(f.w.submitted());assertFalse(f.w.confirmed(true));}
    @Test void figSubmittedCallbackFailureAfterRealConnectionReturnPreservesNativeSubmission(){var f=new F();f.offer();assertTrue(f.w.beforeTransport(f.listener,f.transport,f.packet,true));f.w.transportReturned(true);f.w.bodyReturned(false);assertTrue(f.w.submitted());assertFalse(f.w.confirmed(true));}

    @Test void pendingAssignmentCannotCommitBeforeActualTransportReturn(){var f=new F();f.offer();assertFalse(f.w.beforeCommit(true));assertFalse(f.w.submitted());assertFalse(f.w.confirmed(true));}
    @Test void normalPacketCommitsBeforeLaterNonNormalHelperWithoutGameplayAuthority(){var f=new F();f.offer();assertTrue(f.w.beforeTransport(f.listener,f.transport,f.packet,true));f.w.transportReturned(true);assertTrue(f.w.beforeCommit(true));f.w.cacheReturned();f.w.bodyReturned(false);assertTrue(f.w.submitted());assertFalse(f.w.confirmed(true));}
    @Test void configOnlyRevocationCommitsExactSubmissionBookkeepingWithoutGameplayAuthority(){var f=new F();f.sent();assertTrue(f.w.submitted());assertFalse(f.w.confirmed(false));}
    @Test void foreignNativeCacheWriteRefusesOwnedCommitWithoutErasingActualSubmission(){var f=new F();f.offer();assertTrue(f.w.beforeTransport(f.listener,f.transport,f.packet,true));f.w.transportReturned(true);f.w.bodyReturned(true);assertFalse(f.w.beforeCommit(false));assertTrue(f.w.submitted());assertFalse(f.w.confirmed(true));}
    @Test void cacheHistoryDetectsForeignNativeAbaAndPreservesNewerGeneration(){var h=new NativeCarryPublicationWitness.CacheHistory();var old=h.snapshot();assertTrue(old.current());h.originalWriteReturned();h.originalWriteReturned();assertFalse(old.current());var newer=h.snapshot();assertTrue(newer.current());assertFalse(newer.followsExactlyOne(old));}
    @Test void originalOwnedCacheCommitAdvancesExactlyOnceFromItsCapturedHistory(){var h=new NativeCarryPublicationWitness.CacheHistory();var old=h.snapshot();h.originalWriteReturned();var committed=h.snapshot();assertTrue(committed.followsExactlyOne(old));h.originalWriteReturned();assertFalse(committed.current());}
    @Test void failedNativeCacheWriteLeavesHistoryUnknownInsteadOfForgingReturn(){var h=new NativeCarryPublicationWitness.CacheHistory();var old=h.snapshot();h.originalWriteFailed();assertFalse(old.current());assertFalse(h.snapshot().current());}
    @Test void foreignNativeHistoryCannotBecomeOriginalCommitReceipt(){var h=new NativeCarryPublicationWitness.CacheHistory();var old=h.snapshot();var foreign=new NativeCarryPublicationWitness.CacheHistory();foreign.originalWriteReturned();assertFalse(foreign.snapshot().followsExactlyOne(old));}

    @Test void constructorErrorBeforeRealPacketPreservesErrorAndCannotCommit(){var f=new F();f.cache();var error=new AssertionError("original constructor failure");var caught=assertThrows(AssertionError.class,()->{try{throw error;}finally{f.w.bodyReturned(false);}});assertSame(error,caught);assertFalse(f.w.beforeCommit(true));assertFalse(f.w.submitted());assertFalse(f.w.confirmed(true));}
    @Test void helperErrorAfterRealPacketKeepsCommittedBookkeepingWithoutConfirmation(){var f=new F();f.offer();assertTrue(f.w.beforeTransport(f.listener,f.transport,f.packet,true));f.w.transportReturned(true);assertTrue(f.w.beforeCommit(true));f.w.cacheReturned();var error=new AssertionError("original post-send failure");var caught=assertThrows(AssertionError.class,()->{try{throw error;}finally{f.w.bodyReturned(false);}});assertSame(error,caught);assertTrue(f.w.cacheCommitted());assertFalse(f.w.beforeCommit(true));assertTrue(f.w.submitted());assertFalse(f.w.confirmed(true));}

    @Test void nativeBodyOrderDetectsRawZeroAfterOwnSevenBeforeOuterReturn(){var h=new NativeCarryPublicationWitness.PacketHistory();var own=new Object();var raw=new Object();h.nativeSubmissionReturned(own,7);var old=h.snapshot();h.nativeSubmissionReturned(raw,0);assertFalse(old.current());assertFalse(h.snapshot().latestExact(own,7));assertTrue(h.snapshot().latestExact(raw,0));}
    @Test void rawZeroBeforeActualOwnSevenDoesNotReverseRealSubmissionOrder(){var h=new NativeCarryPublicationWitness.PacketHistory();var own=new Object();h.nativeSubmissionReturned(new Object(),0);h.nativeSubmissionReturned(own,7);assertTrue(h.snapshot().latestExact(own,7));}
    @Test void passiveSamePacketOrderCannotMintOwnedSubmissionReceipt(){var f=new F();f.cache();var h=new NativeCarryPublicationWitness.PacketHistory();h.nativeSubmissionReturned(f.packet,7);assertTrue(h.snapshot().latestExact(f.packet,7));f.w.bodyReturned(true);assertFalse(f.w.submitted());assertFalse(f.w.beforeCommit(true));assertFalse(f.w.confirmed(true));}
    @Test void unknownOrFailedQueueObservationCannotCreditOlderMatchingPacket(){var h=new NativeCarryPublicationWitness.PacketHistory();var packet=new Object();h.nativeSubmissionReturned(packet,7);var old=h.snapshot();h.unknown();assertFalse(old.current());assertFalse(h.snapshot().latestExact(packet,7));}
    @Test void foreignThreadPacketOrderIsUnknownInsteadOfSilentlyRacing() throws Exception {var h=new NativeCarryPublicationWitness.PacketHistory();var packet=new Object();h.nativeSubmissionReturned(packet,7);var old=h.snapshot();var foreign=new Thread(()->h.nativeSubmissionReturned(new Object(),0));foreign.start();foreign.join(5000);assertFalse(foreign.isAlive());assertFalse(old.current());assertFalse(h.snapshot().latestExact(packet,7));}
    @Test void foreignThreadCacheWriterInvalidatesOwnedPendingGeneration() throws Exception {var h=new NativeCarryPublicationWitness.CacheHistory();var old=h.snapshot();var foreign=new Thread(h::originalWriteReturned);foreign.start();foreign.join(5000);assertFalse(foreign.isAlive());assertFalse(old.current());assertFalse(h.snapshot().current());}

    @Test void originalCleanupDeadlineAllowsItsBoundaryButNotOneNanosecondLater(){assertTrue(NativeCarryPublicationWitness.withinOriginalWindow(200,100,150,200));assertFalse(NativeCarryPublicationWitness.withinOriginalWindow(201,100,150,200));}
    @Test void callbackAndFieldReadDelayCannotRefreshOriginalCleanupBudget(){long originalBorn=100,originalDeadline=200;assertTrue(NativeCarryPublicationWitness.withinOriginalWindow(199,originalBorn,150,originalDeadline));assertFalse(NativeCarryPublicationWitness.withinOriginalWindow(201,originalBorn,199,originalDeadline));assertEquals(200,originalDeadline);}
    @Test void cleanupClockRollbackFromLatestReadOrBeforeBirthRefuses(){assertFalse(NativeCarryPublicationWitness.withinOriginalWindow(159,100,160,200));assertFalse(NativeCarryPublicationWitness.withinOriginalWindow(99,100,100,200));assertFalse(NativeCarryPublicationWitness.withinOriginalWindow(150,100,99,200));}
    @Test void originalWindowChecksAvoidElapsedSubtractionOverflow(){assertTrue(NativeCarryPublicationWitness.withinOriginalWindow(Long.MAX_VALUE,Long.MAX_VALUE-2,Long.MAX_VALUE-1,Long.MAX_VALUE));assertFalse(NativeCarryPublicationWitness.withinOriginalWindow(Long.MIN_VALUE,Long.MAX_VALUE-2,Long.MAX_VALUE-1,Long.MAX_VALUE));}
    @Test void gameplayDeadlineOrMenuRevocationDoesNotEraseActualCacheBookkeeping(){var f=new F();f.sent();assertTrue(f.w.submitted());assertTrue(f.w.cacheCommitted());assertFalse(f.w.confirmed(false));}

    @Test void disabledOptionCannotBypassPendingPublicationQuarantine(){var called=new java.util.concurrent.atomic.AtomicBoolean();assertEquals(NativeCarryPublicationWitness.Entry.REVOKED,NativeCarryPublicationWitness.entry(true,false,false,true,true,()->{called.set(true);return false;}));assertFalse(called.get());}
    @Test void disabledOptionCannotBypassRestoringOrRetiredAttempt(){assertEquals(NativeCarryPublicationWitness.Entry.REVOKED,NativeCarryPublicationWitness.entry(false,true,false,true,true,()->{fail("Config must not run while restoring");return false;}));assertEquals(NativeCarryPublicationWitness.Entry.REVOKED,NativeCarryPublicationWitness.entry(false,false,true,true,true,()->{fail("Config must not run after retirement");return false;}));}
    @Test void freshDisabledAndExistingLoanKeepOriginalEntryBehavior(){assertEquals(NativeCarryPublicationWitness.Entry.PRIMARY,NativeCarryPublicationWitness.entry(false,false,false,true,true,()->false));assertEquals(NativeCarryPublicationWitness.Entry.CONTINUE,NativeCarryPublicationWitness.entry(false,false,false,false,false,()->{fail("An existing loan skips disabled fast path");return false;}));assertEquals(NativeCarryPublicationWitness.Entry.CONTINUE,NativeCarryPublicationWitness.entry(false,false,false,true,true,()->true));}

}
